import ifcopenshell
from blender_addon.api.ifc_utils import get_ifc_file
ifc_file = get_ifc_file()
space = ifc_file.by_guid('2UsXAbj6n0fwEWqdkVuHyo')
def get_space_area(space):
    # Try Qto_SpaceBaseQuantities
    qset = ifcopenshell.util.element.get_psets(space, pset_names=["Qto_SpaceBaseQuantities"])
    if qset and "Qto_SpaceBaseQuantities" in qset:
        base_quantities = qset["Qto_SpaceBaseQuantities"]
        area = base_quantities.get("GrossFloorArea")
        if area:
            return float(area)
    # Fallback: calculate from bounding box (geometry dimensions)
    rep = ifcopenshell.util.element.get_representation(space)
    if rep and hasattr(rep, 'geometry'):
        try:
            bbox = rep.geometry.bounding_box()
            area = bbox.dx * bbox.dy
            return float(area)
        except Exception:
            pass
    # Fallback: check geometry attributes
    dims = getattr(space, 'geometry', None)
    if dims and 'dimensions' in dims:
        dx, dy, dz = dims['dimensions']
        area = dx * dy
        return float(area)
    # Fallback: None
    return None
area = get_space_area(space)
area
